151	fn parse_selection(p: &mut GraphqlParser) -> ParsedSyntax {
152	    if is_at_field(p) {
153	        parse_field(p)
154	    } else if is_at_fragment(p) {
155	        parse_fragment(p)
156	    } else {
157	        Absent
158	    }
