13	pub(crate) fn parse_type(p: &mut GraphqlParser) -> ParsedSyntax {
14	    let m = p.start();
15	    let node = if is_at_list_type(p) {
16	        Present(parse_list_type(p))
17	    } else {
18	        parse_named_type(p)
19	    };
20	    if p.at(T![!]) {
21	        p.bump(T![!]);
22	        // cases like `a: !`, having `!` without a type is invalid
23	        node.or_add_diagnostic(p, expected_named_or_list_type);
24	        Present(m.complete(p, GRAPHQL_NON_NULL_TYPE))
25	    } else {
26	        m.abandon(p);
27	        node
28	    }
29	}
